def uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=False):
    """Update a file object so that the location is a reference to the toil file
    store, writing it to the file store if necessary.

    """
    if existing:
        # The file is already in the file store.
        if fileindex.file_size is None:
            # If the size is not known, query the file store.
            fileindex.file_size = uf.size(fileindex.file_id)
        return fileindex

    # The file is not in the file store.
    if fileindex.file_size is None:
        # If the size is not known, query the file store.
        fileindex.file_size = uf.size(fileindex.file_id)

    if fileindex.file_size is None:
        # If the size is still not known, the file is broken.
        if skip_broken:
            return None
        else:
            raise RuntimeError("File %s is broken" % fileindex.file_id)

    # The file is not in the file store, but we know its size.
    fileindex.file_id = uploadfunc(fileindex.file_id, fileindex.file_size)
    return fileindex

